export async function exportGlb(a: Pick<Artwork, 'display' | 'cutout' | 'title'>): Promise<Blob> {
  const { GLTFExporter } = await import('three/examples/jsm/exporters/GLTFExporter.js');
  const { mesh, dispose } = await reliefOf(a, 0.3); // 실물 크기에 가깝게 30cm
  mesh.name = a.title || 'artwork';
  try {
    const out = await new GLTFExporter().parseAsync(mesh, { binary: true });
    return new Blob([out as ArrayBuffer], { type: 'model/gltf-binary' });
  } finally {
    dispose();
  }
}

relief3d.ts::reliefOf.code:
export async function reliefOf(a: Pick<Artwork, 'display' | 'cutout'>, height = 1): Promise<{ mesh: THREE.Mesh; dispose(): void }> {
  const bmp = await createImageBitmap(a.display);
  const c = document.createElement('canvas');
  c.width = bmp.width; c.height = bmp.height;
  c.getContext('2d')!.drawImage(bmp, 0, 0);
  bmp.close?.();
  const texture = new THREE.CanvasTexture(c);
  texture.colorSpace = THREE.SRGBColorSpace;
  let mask = null;
  if (a.cutout) {
    const cb = await createImageBitmap(a.cutout);
    const cc = document.createElement('canvas');
    cc.width = cb.width; cc.height = cb.height;
    cc.getContext('2d')!.drawImage(cb, 0, 0);
    cb.close?.();
    const m = maskFromCutout(cc);
    mask = m.ok ? m : null;
  }
  const mesh = buildRelief(texture, mask, c.width / c.height, { height });
  return {
    mesh,
    dispose() {
      mesh.geometry.dispose();
      (mesh.material as THREE.Material).dispose();
      texture.dispose();
    },
  };
}

cutout.ts::maskFromCutout.code:
export function maskFromCutout(cut: HTMLCanvasElement, side = WORK_SIDE): Mask {
  const { w, h } = fit(cut.width, cut.height, side);
  const c = document.createElement('canvas');
  c.width = w; c.height = h;
  const ctx = c.getContext('2d')!;
  ctx.drawImage(cut, 0, 0, w, h);
  const d = ctx.getImageData(0, 0, w, h).data;
  const m = new Uint8Array(w * h);
  for (let i = 0; i < w * h; i++) m[i] = d[i * 4 + 3]! > 127 ? 1 : 0;
  const lab = keepLargeComponents(m, w, h);
  let n = 0;
  for (let i = 0; i < w * h; i++) n += lab[i] ? 1 : 0;
  const ratio = n / (w * h);
  return { w, h, data: lab, ok: ratio >= 0.03 && ratio <= 0.98, ratio };
}

cutout.ts::buildRelief.code:
export function buildRelief(texture: THREE.Texture, mask: Mask | null, aspect: number, opts: ReliefOptions): THREE.Mesh {
  const H = opts.height;
  const W = H * aspect;
  const depth = opts.depth ?? Math.max(0.03, H * 0.045);
  const shapes: THREE.Shape[] = [];
  const cs = mask ? contours(mask) : [];
  if (cs.length && mask) {
    for (const c of cs) {
      const s = new THREE.Shape();
      c.forEach(([x, y], i) => {
        const X = (x / mask.w - 0.5) * W;
        const Y = (0.5 - y / mask.h) * H;
        if (i === 0) s.moveTo(X, Y); else s.lineTo(X, Y);
      });
      s.closePath();
      shapes.push(s);
    }
  } else {
    const s = new THREE.Shape();
    s.moveTo(-W / 2, -H / 2); s.lineTo(W / 2, -H / 2); s.lineTo(W / 2, H / 2); s.lineTo(-W / 2, H / 2); s.closePath();
    shapes.push(s);
  }
  const bevel = Math.min(depth * 0.35, 0.02);
  const geo = new THREE.ExtrudeGeometry(shapes, { depth, bevelEnabled: true, bevelThickness: bevel, bevelSize: bevel * 0.8, bevelSegments: 1, curveSegments: 1 });
  geo.translate(0, 0, -depth / 2);
  const pos = geo.attributes.position as THREE.BufferAttribute;
  const uv = new Float32Array(pos.count * 2);
  for (let i = 0; i < pos.count; i++) {
    uv[i * 2] = pos.getX(i) / W + 0.5;
    uv[i * 2 + 1] = pos.getY(i) / H + 0.5;
  }
  geo.setAttribute('uv', new THREE.BufferAttribute(uv, 2));
  geo.computeVertexNormals();
  const mat = new THREE.MeshStandardMaterial({ map: texture, roughness: 0.75, metalness: 0, emissive: new THREE.Color(0xffffff), emissiveMap: texture, emissiveIntensity: 0.18 });
  const mesh = new THREE.Mesh(geo, mat);
  mesh.userData.size = { w: W, h: H, d: depth };
  return mesh;
}

