export async function blobToImage(blob: Blob): Promise<HTMLImageElement> {
  const url = URL.createObjectURL(blob);
  try {
    const img = new Image();
    img.decoding = 'async';
    img.src = url;
    await img.decode();
    return img;
  } finally {
    // 디코드가 끝난 뒤에는 주소가 없어도 그려진다
    setTimeout(() => URL.revokeObjectURL(url), 0);
  }
}

