sound.ts::speak.code:
export function speak(text: string): boolean {
  try {
    const ss = window.speechSynthesis;
    if (!ss) return false;
    ss.cancel();
    const u = new SpeechSynthesisUtterance(text);
    u.lang = 'ko-KR';
    u.rate = 0.95;
    const ko = ss.getVoices().find((v) => v.lang.startsWith('ko'));
    if (ko) u.voice = ko;
    ss.speak(u);
    return true;
  } catch {
    return false;
  }
}

